<?php requireAdmin(); $users=db()->query("SELECT id,username,display_name,role FROM users ORDER BY username")->fetchAll(); $items=db()->query('SELECT * FROM menu_items ORDER BY COALESCE(parent_id,id), sort_order')->fetchAll(); $perms=db()->query('SELECT user_id, menu_item_id FROM user_menu_permissions WHERE can_access=1')->fetchAll(); $map=[]; foreach($perms as $p){$map[$p['user_id']][$p['menu_item_id']]=true;} ?>
<div class="panel"><h2>Rechteverwaltung</h2><div class="notice">Admins haben automatisch Zugriff auf alle Menüpunkte; Einzelrechte sind vor allem für Benutzer mit Rolle user relevant.</div></div>
<?php foreach($users as $u): ?><div class="panel"><h3><?= e($u['display_name']) ?> (<?= e($u['role']) ?>)</h3><form class="ajax-form" action="ajax/admin_permissions.php" data-reload="admin_permissions" method="post"><?= csrfField() ?><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><?php foreach($items as $i): ?><label style="display:block;margin:5px 0 <?= $i['parent_id']?'5px 22px':'5px 0' ?>"><input type="checkbox" name="menu_ids[]" value="<?= (int)$i['id'] ?>" <?= isset($map[$u['id']][$i['id']])||$u['role']==='admin'?'checked':'' ?>> <?= e($i['title']) ?> <span class="muted"><?= e($i['module_key'] ?: '') ?></span></label><?php endforeach; ?><button>Rechte speichern</button></form></div><?php endforeach; ?>
